INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"50283123-e810-46f1-b611-20c60920a3bf"}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 1, $s$text$s$, $s${"html":"We were excited to explore Tobago's underwater wonders today! We met our tour guide at 📌Pigeon Point Beach (ℹ️ entrance fee applies), passing by 📌Store Bay Beach, where locals enjoyed a leisurely swim. The vibrant stalls selling local art along the way added a touch of local color. The beach is simply idyllic, think soft white sand, swaying palm trees, and clear turquoise water. It's truly a picture-perfect Caribbean paradise! Note, on the way to Pigeon Point, you'll spot some charming local stalls selling all sorts of vibrant, local art. It's a great chance to grab a unique souvenir!"}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 2, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1853","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1854","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1860","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1852","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1851","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1867 2","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1889","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1868"]}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 3, $s$text$s$, $s${"html":"Our first stop, the 📌Nylon Pool, named after Princess Margaret, was a magical experience. She likened the pool's crystal-clear water to the transparency of nylon, a fitting description for its remarkable clarity. Locals believe that swimming in these turquoise waters possesses rejuvenating powers. The crystal-clear water was simply mesmerizing."}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 4, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1861","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1911","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1908","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1916"]}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 5, $s$text$s$, $s${"html":"We then explored the vibrant 📌Buccoo Reef, encountering a dazzling array of marine life. It was a living, breathing kaleidoscope down there – the corals were vibrant, and I just kept seeing schools of bright, colorful fish zipping past in every direction. It truly felt like an underwater wonderland!"}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 6, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1893 2","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1894","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1900","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1898"]}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 7, $s$text$s$, $s${"html":"Our boat trip had another fantastic surprise: a stop at No Man's Land, a secluded, pristine white-sand beach accessible only by boat! It wasn't on our original plan, but it turned out to be this incredible, tiny slice of paradise. The water was just ridiculously clear, and the best part? Locals were right there, selling the freshest seafood, which made for the perfect, spontaneous moment of pure relaxation and a delicious treat, before returning to Pigeon Point to relax and enjoy the afternoon."}$s$::jsonb),
  ($s$1d890bb4-3c0b-4c83-8e30-eb305bcd4748$s$, 8, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1923","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1922","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1939","aroundtheworld50s/blog/trinidad-and-tobago/6/IMG_1885"]}$s$::jsonb);
